  ["data.otservbr.global.npc.a.fluffy.squirrel.L73.1054"] = "Чх...",
  ["data.otservbr.global.npc.a.fluffy.squirrel.L74.1055"] = "[EN] Chchch. Chh! <you're not sure, but it seems that squirrel wants to trade your valuable acorns for useless stones that it found and considered uneatable>",
  ["data.otservbr.global.npc.a.frog.L57.1456"] = "[EN] *sigh* Yet another dumb adventurer.",
