  ["data.otservbr.global.npc.a.frog.L59.1458"] = "[EN] Hah! That idiot finally left.",
  ["data.otservbr.global.npc.a.ghostly.sage.L60.1103"] = "[EN] Ah, I feel a mortal walks these ancient halls again. Pardon me, I barely notice you. I am so lost in my thoughts.",
  ["data.otservbr.global.npc.a.ghostly.sage.L61.1104"] = "До свидания.",
  ["data.otservbr.global.npc.a.ghostly.sage.L62.1105"] = "[EN] Farewell then.",
  ["data.otservbr.global.npc.a.ghostly.woman.L62.1178"] = "[EN] I feel you. I hear your thoughts. You are ... alive.",
  ["data.otservbr.global.npc.a.ghostly.woman.L63.1179"] = "[EN] Alone ... so alone. So cold.",
  ["data.otservbr.global.npc.a.ghostly.woman.L64.1180"] = "[EN] Alone ... so alone. So cold.",
