  ["data.otservbr.global.npc.a.prisoner.L138.261"] = "[EN] Wait! Don't leave! I want to tell you about my surreal numbers.",
  ["data.otservbr.global.npc.a.prisoner.L139.262"] = "[EN] Good bye! Don't forget about the secrets of mathemagics.",
  ["data.otservbr.global.npc.a.prisoner.L140.263"] = "[EN] Huh? What? I can see! Wow! A non-mino. Did they {capture} you as well?",
  ["data.otservbr.global.npc.a.restless.soul.L53.44"] = "Уххх...",
  ["data.otservbr.global.npc.a.restless.soul.L56.45"] = "[EN] Ahhhh! At last someone that can listen to my {story}!",
  ["data.otservbr.global.npc.a.sleeping.dragon.L51.150"] = "[EN] ZzzzZzzZz...chrrr...",
  ["data.otservbr.global.npc.a.sleeping.dragon.L53.151"] = "[EN] Greetings, {wayfarer}.",
  ["data.otservbr.global.npc.a.strange.chalice.L117.1623"] = "[EN] Hi? What do you mean 'hi' - can't you see I am a... I have to lower my voice. Did it occur to you, that this 'chalice' does not want to be disturbed?! Leave me alone!",
  ["data.otservbr.global.npc.a.swan.L95.88"] = "[EN] I salute you, mortal being.",
  ["data.otservbr.global.npc.a.sweaty.cyclops.L227.68"] = "[EN] Hum Humm! Welcume lil' |PLAYERNAME|.",
  ["data.otservbr.global.npc.a.sweaty.cyclops.L228.69"] = "[EN] Good bye lil' one.",
  ["data.otservbr.global.npc.a.vulcongra.L56.934"] = "[EN] Pssst! Keep it down! <gives you an elaborate report on monster activity>",
  ["data.otservbr.global.npc.a.vulcongra.L65.935"] = "[EN] Pssst! Keep it down! <gives you an elaborate report on monster activity>",
  ["data.otservbr.global.npc.a.vulcongra.L72.936"] = "[EN] Pssst! Keep it down! <gives you an elaborate report on monster activity>",
  ["data.otservbr.global.npc.a.weakened.forest.fury.L122.711"] = "[EN] I greet you, human. This is a time of distress, more than ever are we in need of guardians to protect us and our world.",
  ["data.otservbr.global.npc.a.wrinkled.bonelord.L80.1421"] = "[EN] What is this? An optically challenged entity called |PLAYERNAME|. How fascinating!",
  ["data.otservbr.global.npc.a.wrinkled.bonelord.L81.1422"] = "[EN] Wait right there. I will eat you after writing down what I found out.",
  ["data.otservbr.global.npc.a.wrinkled.bonelord.L82.1423"] = "[EN] Wait right there. I will eat you after writing down what I found out.",
  ["data.otservbr.global.npc.a.wyrm.L56.1560"] = "[EN] Pssst! Keep it down! <gives you an elaborate report on monster activity>",
  ["data.otservbr.global.npc.a.wyrm.L65.1561"] = "[EN] Pssst! Keep it down! <gives you an elaborate report on monster activity>",
  ["data.otservbr.global.npc.a.wyrm.L72.1562"] = "[EN] Pssst! Keep it down! <gives you an elaborate report on monster activity>",
  ["data.otservbr.global.npc.ahmet.L182.407"] = "[EN] Be mourned pilgrim in flesh. I'm selling general goods. Just ask me for a {trade}.",
  ["data.otservbr.global.npc.ajax.L58.355"] = "[EN] You back. You know, you right. Brother is right. Fist not always good. Tell him that!",
  ["data.otservbr.global.npc.ajax.L61.356"] = "[EN] Whatcha do in my place?",
  ["data.otservbr.global.npc.al.dee.L166.596"] = "Пока-пока.",
  ["data.otservbr.global.npc.al.dee.L167.597"] = "[EN] Bye, bye |PLAYERNAME|.",
  ["data.otservbr.global.npc.al.dee.L168.598"] = "[EN] Take a look in the trade window to your left.",
  ["data.otservbr.global.npc.albinius.L267.1035"] = "[EN] Greetings, pilgrim. Welcome to the halls of hope. We are the keepers of this {temple} and welcome everyone willing to contribute.",
  ["data.otservbr.global.npc.albinius.L268.1036"] = "[EN] Oh... farewell, child.",
  ["data.otservbr.global.npc.alesar.L206.1591"] = "Окончательно.",
  ["data.otservbr.global.npc.alesar.L207.1592"] = "Окончательно.",
  ["data.otservbr.global.npc.alesar.L208.1593"] = "[EN] At your service, just browse through my wares.",
  ["data.otservbr.global.npc.alexander.L171.1567"] = "[EN] Hi there |PLAYERNAME|, and welcome to the {magic} store.",
  ["data.otservbr.global.npc.alexander.L172.1568"] = "[EN] See you, |PLAYERNAME|.",
  ["data.otservbr.global.npc.alexander.L173.1569"] = "[EN] See you, |PLAYERNAME|.",
  ["data.otservbr.global.npc.alexander.L174.1570"] = "[EN] Of course, just browse through my wares. Or do you want to look only at",
  ["data.otservbr.global.npc.alia.L148.1158"] = "[EN] Welcome, young |PLAYERNAME|! If you are heavily wounded or poisoned, I can {heal} you for free.",
  ["data.otservbr.global.npc.alia.L149.1159"] = "[EN] Remember: If you are heavily wounded or poisoned, I can heal you for free.",
  ["data.otservbr.global.npc.alia.L150.1160"] = "[EN] May the gods bless you, |PLAYERNAME|!",
  ["data.otservbr.global.npc.alkestios.L130.1473"] = "[EN] Nature's blessing, traveller! May you not be affected by any sinister force.",
  ["data.otservbr.global.npc.alkestios.L131.1474"] = "[EN] May your path always be even.",
  ["data.otservbr.global.npc.alkestios.L132.1475"] = "[EN] May your path always be even.",
  ["data.otservbr.global.npc.altar.L83.730"] = "[EN] Kneel before the all-devouring power of blooded decay.",
  ["data.otservbr.global.npc.altar.L84.731"] = "Пока.",
  ["data.otservbr.global.npc.altar.L85.732"] = "[EN] Bye, |PLAYERNAME|.",
  ["data.otservbr.global.npc.alyxo.L210.798"] = "[EN] Well, bye then.",
  ["data.otservbr.global.npc.alyxo.L53.795"] = "[EN] How could I help you?",
  ["data.otservbr.global.npc.alyxo.L56.796"] = "[EN] How could I help you?",
  ["data.otservbr.global.npc.alyxo.L59.797"] = "[EN] How could I help you?",
  ["data.otservbr.global.npc.amanda.L200.1226"] = "[EN] Welcome, young |PLAYERNAME|! If you are heavily wounded or poisoned, I can {heal} you for free.",
  ["data.otservbr.global.npc.amanda.L201.1227"] = "[EN] Remember: If you are heavily wounded or poisoned, I can heal you for free.",
  ["data.otservbr.global.npc.amanda.L202.1228"] = "[EN] May the gods bless you, |PLAYERNAME|!",
  ["data.otservbr.global.npc.ambassador.of.rathleton.L86.343"] = "[EN] Greetings, friend.",
  ["data.otservbr.global.npc.ambassador.of.rathleton.L87.344"] = "[EN] Well, bye then.",
  ["data.otservbr.global.npc.amber.L426.528"] = "[EN] Yeah, see you later.",
  ["data.otservbr.global.npc.amber.L427.529"] = "[EN] See you later, |PLAYERNAME|.",
  ["data.otservbr.global.npc.amber.L428.530"] = "[EN] Oh hello, nice to see you |PLAYERNAME|. Are you here to hear some stories of my {adventures} or do you need {help}?",
  ["data.otservbr.global.npc.anderson.L100.133"] = "[EN] Ahoi, young man |PLAYERNAME| and welcome to the Nordic Tibia Ferries. If you need a {passage}, let me know.",
  ["data.otservbr.global.npc.anderson.L101.134"] = "[EN] Good bye. You are welcome.",
  ["data.otservbr.global.npc.andrew.lyze.L101.514"] = "[EN] Hello, I am the warden of this {monument}. The {sarcophagus} in front of you was established to prevent people from going {down} there. But I doubt that this step is sufficient.",
  ["data.otservbr.global.npc.andrew.lyze.L103.515"] = "[EN] Well, let's see if your mission was successful. Just bring me all needed {materials}.",
  ["data.otservbr.global.npc.andrew.lyze.L105.516"] = "[EN] If you dug up all three crystals of sufficient quantity and obtained the poison gland, the charging of your compass can start! For the very first time it will be charged by the violet crystal. Ready to {unleash} the power of the crystals?",
  ["data.otservbr.global.npc.andrew.lyze.L107.517"] = "Привет.",
  ["data.otservbr.global.npc.andrew.lyze.L263.518"] = "[EN] Well, bye then.",
  ["data.otservbr.global.npc.andrew.lyze.L264.519"] = "До свидания.",
  ["data.otservbr.global.npc.anerui.L71.1487"] = "[EN] Ashari |PLAYERNAME|.",
  ["data.otservbr.global.npc.anerui.L72.1488"] = "[EN] Asha Thrazi.",
  ["data.otservbr.global.npc.anerui.L73.1489"] = "[EN] Asha Thrazi.",
  ["data.otservbr.global.npc.aneus.L130.1323"] = "[EN] Greetings adventurer |PLAYERNAME|. What leads you to me?",
  ["data.otservbr.global.npc.aneus.L131.1324"] = "[EN] Good bye and take care of you!",
  ["data.otservbr.global.npc.angelina.L58.143"] = "[EN] The gods must be praised that I am finally saved. I do not have many worldly possessions, but please accept a small reward, do you?",
  ["data.otservbr.global.npc.angelina.L60.144"] = "[EN] Thanks for saving my life! Should I teleport you out of the Dark Cathedral?",
  ["data.otservbr.global.npc.angelina.L84.145"] = "[EN] May the gods bless you.",
  ["data.otservbr.global.npc.angelina.L85.146"] = "[EN] May the gods bless you.",
  ["data.otservbr.global.npc.angelo.L153.1447"] = "[EN] Well, bye then.",
  ["data.otservbr.global.npc.angelo.L58.1443"] = "[EN] The Druid of Crunor? He told you that a new cave appeared here? That's right. I'm the head of a {project} that tries to find out more about this new {area}.",
  ["data.otservbr.global.npc.angelo.L60.1444"] = "[EN] Just get out of my way! You killed this beautiful creature. I have nothing more to say. Damn druid of Crunor!",
  ["data.otservbr.global.npc.angelo.L62.1445"] = "[EN] How is your {mission} going?",
  ["data.otservbr.global.npc.angelo.L64.1446"] = "[EN] The Druid of Crunor? He told you that a new cave appeared here? That's right. I'm the head of a project that tries to find out more about this new area.",
  ["data.otservbr.global.npc.angus.L633.1450"] = "[EN] Greetings, what can I do for you?",
  ["data.otservbr.global.npc.appaloosa.L109.1145"] = "[EN] Salutations, |PLAYERNAME| I guess you are here for the {horses}.",
  ["data.otservbr.global.npc.archery.L64.538"] = "[EN] Welcome to Archery's shop!",
  ["data.otservbr.global.npc.archery.L65.539"] = "[EN] Please come back from time to time.",
  ["data.otservbr.global.npc.archery.L66.540"] = "[EN] Please come back from time to time.",
  ["data.otservbr.global.npc.archery.rook.L63.70"] = "[EN] Welcome to Archery's Rook shop.",
  ["data.otservbr.global.npc.archery.rook.L64.71"] = "[EN] Please come back from time to time.",
  ["data.otservbr.global.npc.archery.rook.L65.72"] = "[EN] Please come back from time to time.",
  ["data.otservbr.global.npc.ariella.L161.242"] = "Всем привет.",
  ["data.otservbr.global.npc.arito.L117.1343"] = "[EN] Do visit us again.",
  ["data.otservbr.global.npc.arito.L118.1344"] = "[EN] Do visit us again.",
  ["data.otservbr.global.npc.arito.L119.1345"] = "[EN] Sure, browse through my offers.",
  ["data.otservbr.global.npc.arito.L55.1341"] = "[EN] Thank god you are back!! Did you find....err...what we were talking about??",
  ["data.otservbr.global.npc.arito.L57.1342"] = "[EN] Be mourned, pilgrim in flesh. Be mourned in my tavern.",
  ["data.otservbr.global.npc.arkarra.L54.501"] = "...",
  ["data.otservbr.global.npc.arkarra.L55.502"] = "...",
  ["data.otservbr.global.npc.arkarra.L56.503"] = "...",
  ["data.otservbr.global.npc.arkulius.L183.893"] = "[EN] Good bye and please stay away, okay?",
  ["data.otservbr.global.npc.arkulius.L184.894"] = "[EN] At last! Good things come to those who wait.",
  ["data.otservbr.global.npc.armenius.L74.643"] = "[EN] Oh, the nerve. Go to the rats which raised you.",
  ["data.otservbr.global.npc.armenius.L86.644"] = "[EN] Ah, an adventurer. Be greeted and have a seat. How may I {serve} you?",
  ["data.otservbr.global.npc.aruda.L256.1338"] = "[EN] I hope to see you soon.",
  ["data.otservbr.global.npc.aruda.L257.1339"] = "[EN] Good bye, |PLAYERNAME|. I really hope we'll talk again soon.",
  ["data.otservbr.global.npc.aruda.L64.1336"] = "[EN] Oh, hello |PLAYERNAME|, your hair looks great! Who did it for you?",
  ["data.otservbr.global.npc.aruda.L67.1337"] = "[EN] Oh, hello, handsome! It's a pleasure to meet you, |PLAYERNAME|. Gladly I have the time to {chat} a bit.",
  ["data.otservbr.global.npc.ashari.L52.1581"] = "[EN] Hello, stranger! These caves must seem strange to you. I wonder what brings you here... maybe you are interested in some work? There are several tasks I could need a hand with.",
  ["data.otservbr.global.npc.ashari.L53.1582"] = "Пока!",
  ["data.otservbr.global.npc.ashari.L54.1583"] = "Пока!",
  ["data.otservbr.global.npc.asima.L179.1417"] = "[EN] Of course, just browse through my wares. Or do you want to look only at",
  ["data.otservbr.global.npc.atur.L76.727"] = "[EN] Yes? What may I do for you, |PLAYERNAME|? Bank business, perhaps?",
  ["data.otservbr.global.npc.atur.L77.728"] = "[EN] Have a nice day.",
  ["data.otservbr.global.npc.atur.L78.729"] = "[EN] Have a nice day.",
  ["data.otservbr.global.npc.aurita.L114.171"] = "[EN] Greetings, traveller!",
  ["data.otservbr.global.npc.aurita.L115.172"] = "[EN] May your path always be even.",
  ["data.otservbr.global.npc.aurita.L116.173"] = "[EN] May your path always be even.",
  ["data.otservbr.global.npc.avar.tar.L137.859"] = "[EN] Greetings, traveller |PLAYERNAME|!",
  ["data.otservbr.global.npc.avar.tar.L138.860"] = "[EN] See you later, |PLAYERNAME|.",
  ["data.otservbr.global.npc.avar.tar.L139.861"] = "[EN] See you later, |PLAYERNAME|.",
  ["data.otservbr.global.npc.awarness.of.the.emperor.L50.141"] = "[EN] I am not here to fight you, fool. Like it or not, we will have to work together to stop the catastrophe you and that priest have initiated.",
  ["data.otservbr.global.npc.awarness.of.the.emperor.L52.142"] = "[EN] Greetings, mortal. Be aware that you are trying my patience while we are talking.",
  ["data.otservbr.global.npc.azalea.L148.851"] = "[EN] Welcome, young |PLAYERNAME|! If you are heavily wounded or poisoned, I can {heal} you for free.",
  ["data.otservbr.global.npc.azalea.L149.852"] = "[EN] Remember: If you are heavily wounded or poisoned, I can heal you for free.",
  ["data.otservbr.global.npc.azalea.L150.853"] = "[EN] May the gods bless you, |PLAYERNAME|!",
  ["data.otservbr.global.npc.baa.leal.L158.273"] = "[EN] Stand down, soldier!",
  ["data.otservbr.global.npc.bambi.bonecrusher.L76.573"] = "[EN] LONG LIVE THE QUEEN!",
  ["data.otservbr.global.npc.bambi.bonecrusher.L77.574"] = "[EN] LONG LIVE THE QUEEN!",
  ["data.otservbr.global.npc.bambi.bonecrusher.L78.575"] = "[EN] LONG LIVE THE QUEEN!",
  ["data.otservbr.global.npc.barazbaz.L93.18"] = "[EN] Oh, hello there!",
  ["data.otservbr.global.npc.barbara.L84.1299"] = "[EN] LONG LIVE THE QUEEN!",
  ["data.otservbr.global.npc.barbara.L85.1300"] = "[EN] LONG LIVE THE QUEEN! You may leave now!",
  ["data.otservbr.global.npc.barnabas.dee.L130.1046"] = "[EN] Welcome to my humble abode. If you come for new sorcerer {spells}, you have come to the right place.",
  ["data.otservbr.global.npc.barnabas.dee.L131.1047"] = "[EN] Take care, child",
  ["data.otservbr.global.npc.barnabas.dee.L132.1048"] = "[EN] 'The impetuosity of youth', as my friend Mordecai would say.",
  ["data.otservbr.global.npc.bashira.L63.1584"] = "[EN] Welcome, |PLAYERNAME|.",
  ["data.otservbr.global.npc.bashira.L64.1585"] = "[EN] Good Bye, |PLAYERNAME|.",
  ["data.otservbr.global.npc.bashira.L65.1586"] = "[EN] May God show you the path, |PLAYERNAME|.",
  ["data.otservbr.global.npc.bashira.L66.1587"] = "[EN] Of course, just browse through my offers.",
  ["data.otservbr.global.npc.battlemart.L64.1360"] = "[EN] It is good to see you. I'm always at your {shop options}",
  ["data.otservbr.global.npc.battlemart.L65.1361"] = "[EN] Farewell, |PLAYERNAME|, I'll be here if you need me again.",
  ["data.otservbr.global.npc.battlemart.L66.1362"] = "[EN] Come back soon!",
  ["data.otservbr.global.npc.battlemart.L67.1363"] = "[EN] Of course, just browse through my wares. Or do you want to look only at",
  ["data.otservbr.global.npc.baxter.L60.1236"] = "[EN] LONG LIVE KING TIBIANUS!",
  ["data.otservbr.global.npc.baxter.L61.1237"] = "[EN] LONG LIVE THE KING!",
  ["data.otservbr.global.npc.baxter.L62.1238"] = "[EN] LONG LIVE THE KING!",
  ["data.otservbr.global.npc.baxter.L63.1239"] = "[EN] Do you bring freshly killed rats for a bounty of 1 gold each? By the way, I also buy orc teeth and other stuff you ripped from their bloody corp... I mean... well, you know what I mean.",
