  ["data.otservbr.global.npc.caramellia.L100.981"] = "[EN] Hello, |PLAYERNAME|. Please leave me alone in my {mourning}.",
  ["data.otservbr.global.npc.carina.L97.831"] = "[EN] Welcome, |PLAYERNAME|. I am looking forward to trade with you.",
  ["data.otservbr.global.npc.carlos.L100.1093"] = "[EN] Welcome back |PLAYERNAME|, I hope you changed your mind and will bring me some {meat}? I'll even give you some gold for it.",
  ["data.otservbr.global.npc.carlos.L103.1094"] = "[EN] Welcome back, |PLAYERNAME|! Did you have a successful hunt and carry a piece of {meat} or ham with you?",
  ["data.otservbr.global.npc.carlos.L107.1095"] = "[EN] Welcome back, Isleth Eagonst! Do you still have that piece of meat or ham? If so, please ask me for a {trade} and I'll give you some gold for it.",
  ["data.otservbr.global.npc.carlos.L110.1096"] = "[EN] Welcome back, |PLAYERNAME|! Where did you put that delicious piece of food? Did you eat it yourself? Well, if you find another one, please come back.",
  ["data.otservbr.global.npc.carlos.L115.1097"] = "[EN] Hey there, |PLAYERNAME|! Well, that's how trading with NPCs like me works. I think you are ready now to cross the bridge to Rookgaard! Take care!",
  ["data.otservbr.global.npc.carlos.L121.1098"] = "[EN] Hello again, |PLAYERNAME|! What are you still doing here? You should head over the bridge to Rookgaard village now!",
  ["data.otservbr.global.npc.carlos.L241.1099"] = "[EN] Very nice! Food for me! Sell it to me, fast! Once you sold your food to me, just say {ready} to let me know you are done.",
  ["data.otservbr.global.npc.carlos.L242.1100"] = "[EN] Good bye |PLAYERNAME|!.",
  ["data.otservbr.global.npc.carlos.L243.1101"] = "[EN] Good bye traveller and enjoy your stay on Rookgaard.",
  ["data.otservbr.global.npc.carlos.L86.1089"] = "[EN] Be greeted, |PLAYERNAME|! As a tailor and merchant I have to say - we need to do something about your {outfit}, shall we?",
  ["data.otservbr.global.npc.carlos.L91.1090"] = "[EN] Hey, I thought you were going to run away, but luckily you came back. I'll show you how to change your {outfit}, okay?",
  ["data.otservbr.global.npc.carlos.L94.1091"] = "[EN] Welcome back! You know, after providing my little outfit service, I like to ask a little favour of you. Can you {help} me?",
  ["data.otservbr.global.npc.carlos.L97.1092"] = "[EN] Oh hey |PLAYERNAME|, you didn't answer my question yet - could you help me get some {food}? I'll even give you some gold for it.",
  ["data.otservbr.global.npc.cassino.L250.349"] = "[EN] Welcome to the Cassino! Here we play with: \\n [PAYOUT 180%] {HIGH / LOW}: High for 4, 5, 6 and Low for 1, 2, and 3 - {ODD / EVEN }: Odd for 1, 3, 5 and Even for 2, 4 and 6 \\n [PAYOUT 500%] {NUMBERS}: You choose the number, and if you get it right ... {$$$$$}",
  ["data.otservbr.global.npc.cassino.L251.350"] = "До свидания.",
