  ["data.otservbr.global.npc.vascalir.L100.1525"] = "[EN] Welcome back, |PLAYERNAME|. Glad to see you made it back in one piece. I hope you're not too exhausted, because I could use your {help} again.",
  ["data.otservbr.global.npc.vascalir.L103.1526"] = "[EN] Oh, hello |PLAYERNAME|! Have you made up your mind about sneaking into the tarantula's lair and retrieving a sample of her web? Are you up for it?",
