  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.analyser.L20.2105"] = "[EN] Well done! The water is analyzed.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.counter.agent.L37.2085"] = "[EN] A sandstorm has destroyed almost all pillars. The effect of the counteragent worked different than expected.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.counter.agent.L38.2086"] = "[EN] The sandstorm has not only destroyed the oasis, but also revealed some paving tiles and a lever.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.crate.L11.2083"] = "[EN] You already took the magnifier.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.crate.L13.2084"] = "[EN] This crate belongs to Angelo. You should talk to him before taking something out.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.crate.L7.2082"] = "[EN] Perfect! You took a wonderful loupe from this crate.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L10.2103"] = "[EN] So for a small expense allowance you'll get it back. Just talk to Iwar in Kazordoon for further information.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L11.2104"] = "[EN] Ask him: Has the cat got your tongue?",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L7.2100"] = "[EN] Dear curator, this recently opened museum is a really nice place to be.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L8.2101"] = "[EN] But wait! What about the empty space in front of you? What a pity!",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L9.2102"] = "[EN] It seems that somebody has removed one of the beautiful pictures. But come on! You have the money and we need it.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.last.object.L23.2096"] = "[EN] The strange symbol in the wall in the back glows violently.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.last.object.L24.2097"] = "[EN] The cult object just lies there quietly. The dangerous area around it has been all but dissolved.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.last.object.L25.2098"] = "[EN] As you reach out to touch the cult object, a surge of energy burst from the skull. You banished its power.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.magnifier.L19.2122"] = "[EN] Nothing special. This picture looks genuine.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.magnifier.L24.2123"] = "[EN] This is it. It looks like it was painted by a child!",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.misguided.L62.2109"] = "[EN] You paralyse the bully and the amulet reveals the true face of the creature behind the possession of this misguided creature.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.torch.L18.2116"] = "[EN] You hear a loud grinding sound not very far from you. something very heavy seems to have moved.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.begin.task.L36.2106"] = "[EN] The amulet burns your skin. It hungers for energy right now, gather a large amount of energy as fast as possible to charge it.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.check.oasis.L10.2108"] = "[EN] You have found a lovely oasis with green fauna and juicy fruit. You didn't expect that.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.energy.fence.L31.2117"] = "[EN] With you being the vessel binding the power of whitered souls, you step through the magic barrier.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.energy.fence.L35.2118"] = "[EN] The combined powers of decaying souls roaming these halls may help breach this barrier, it needs but a vessel to bind them.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.energy.fence.L39.2119"] = "[EN] With you being the vessel binding the power of whitered souls, you step through the magic barrier.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.energy.fence.L43.2120"] = "[EN] The combined powers of decaying souls roaming these halls may help breach this barrier, it needs but a vessel to bind them.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.energy.fence.L49.2121"] = "[EN] As you cross the threshold in to the inner sanctuary of the cult of the Misguided, you feel an eerie presence all around you.",
