  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.ice.death.L63.2088"] = "[EN] You are still blessed with Wisdom of Solitude, Spark of the Phoenix, Fire of the Suns, Spiritual Shielding, Embrace of Tibia, Heart of the Mountain, Blood of the Mountain, and Twist of Fate.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.ice.death.L64.2089"] = "[EN] You lost 0 experience and 0.00% of all of your skills.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.ice.death.L65.2090"] = "[EN] You did not lose any items.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.ice.death.L68.2091"] = "[EN] The cold has all but disappeared from your body and you're getting warmer. You need to renew all preparations for purification.",
