  ["data.otservbr.global.scripts.quests.the.cursed.crystal.movements.StepIn.CursedCrystal.L41.1778"] = "[EN] This small room could once have been a shrine of some kind. You discover an old inscription between two ornate stone walls.",
  ["data.otservbr.global.scripts.quests.the.cursed.crystal.movements.StepIn.CursedCrystal.L42.1779"] = "[EN] The text is partly crumbled: 'Take ... vial of emb... fl... and mix ... a medusa's bl.... Then .. the dust of ... crystal, so ... will get the Medusa's Ointm... powerful ... able to unpetrify ...",
  ["data.otservbr.global.scripts.quests.the.djinn.war.quest.action.water.fountain.L10.1917"] = "[EN] You have found a tear of daraman.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.acidFishingRod.L23.1839"] = "[EN] You dare not touch there remains. A word has been carved into these bones over and over: 'K'muuh'.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.bookOnTable.L14.1855"] = "[EN] This book tells you about a spell that draws its wielder towards the most energetic being next to him.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.bookOnTable.L15.1856"] = "[EN] It consists of four parts wich have been scratched out of this book. They need to be read in conjunction with chants.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.bookOnTable.L18.1857"] = "[EN] You have to wait to challange this enemy again!",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.bookOnTable.L22.1858"] = "[EN] All chants have been sung in the right order, you are deemed worthy. You are transported away...",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.containerRewards.L125.1842"] = "[EN] You have found a",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.containerRewards.L140.1843"] = "[EN] It is empty.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.doorInvisible.L14.1844"] = "[EN] The door opens.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.dreamcatcher.curse.L40.1848"] = "[EN] You can rip off a dream catcher!",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.dreamcatcher.curse.L54.1849"] = "[EN] You have a feeling of dread.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.dreamcatcher.curse.L57.1850"] = "[EN] You take the dreamcurse on yourself!",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.goldenIdol.L51.1846"] = "[EN] You have placed all the idols on the altars and unlocked the temple!",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.goldenIdol.L56.1847"] = "[EN] There is already an idol here. Try another altar.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.keyCheck.L18.1830"] = "[EN] As soon as you turn the second key a mechanism retracts the locks and swallows the keys, opening a small passage beyond.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.keyCheck.L22.1831"] = "[EN] You need to use the mechanism of the pillar itself to turn both keys at once.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.keyCheck.L26.1832"] = "[EN] You reach for the onyx and trigger and enormous discharge of raw energy. It is now possible to traverse the portal in this tomb.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.magicalPaint.L24.1837"] = "[EN] Carefully you paint over the picture. As you are doing so the flat paiting deepens. It looks now like a room you can enter.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.magicalPaint.L38.1838"] = "[EN] This isn't a normal paiting anymore. By using magical paint you transformed it into a portal and can easily pass it.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.oldLock.L15.1845"] = "[EN] You insert the old lock into the door. It fits perfectly.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.questDoors.L108.1859"] = "[EN] The door seems to be sealed against unwanted intruders.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.questDoors.L115.1860"] = "[EN] As Medusa's Ointment takes effect, the door is unpetrified. You can use it now.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.questDoors.L128.1861"] = "[EN] The lock in this door is missing. Perhaps you can find a matching lock somewhere?",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.questDoors.L141.1862"] = "[EN] The door seems to be sealed against unwanted intruders.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.rosebushUse.L16.1851"] = "[EN] You plant the rosebush into the fresh soil. The green portal glows brighter. Perhaps you may pass it now.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.sacrophagusUse.L41.1840"] = "[EN] The curse of disturbing this fragile, ancient peace is your price to pay!",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.sacrophagusUse.L47.1841"] = "[EN] The opening of the last sarcophagus still haunts you. Wait some time for your spirits to return.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.strangeBucket.L37.1833"] = "[EN] There is not enough ectoplasm left to fill it in the bucket.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.strangeBucket.L43.1834"] = "[EN] There is not enough ectoplasm left to fill it in the bucket.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.strangeBucket.L49.1835"] = "[EN] The ectoplasm all over this egg was already seeping inside the cocoon itself. You manage to fill soem of it into the bucket.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.strangeBucket.L69.1836"] = "[EN] You pour all of the ectoplasm over yourself. Without the bucket you cannot stabilise it, you need to hurry until it dissolves!",
