  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L234.1697"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L72.1690"] = "[EN] You have no business down there.",
