  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission07.attack.L152.1743"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission07.attack.L77.1739"] = "[EN] You're coughing so badly that you had to return upstairs. Take a few deep breaths and try again.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission07.attack.L97.1740"] = "[EN] This fire is much too hot to walk through it. Use the destroy field rune on the fire to weaken the flames!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L118.1734"] = "[EN] You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L122.1735"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L159.1736"] = "[EN] That should weaken the beam enough to make it collapse soon.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L161.1737"] = "[EN] This was the last beam. Now, get out of here before the cave collapses!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L169.1738"] = "[EN] You've already weakened this beam. Better leave it alone now so it won't collapse before you are out of here.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L74.1732"] = "[EN] You have no business down there.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L77.1733"] = "[EN] The cave has collapsed. It's not safe to go down there anymore.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission10.tomb.raiding.L142.1747"] = "[EN] You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission10.tomb.raiding.L144.1748"] = "[EN] You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission10.tomb.raiding.L149.1749"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission10.tomb.raiding.L91.1745"] = "[EN] You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission10.tomb.raiding.L95.1746"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission11.sweet.poison.L59.1744"] = "[EN] You carefully gather some of the wasp poison. Bring it back to Vascalir.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L178.1703"] = "[EN] You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L183.1704"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L209.1705"] = "[EN] You knock the unsuspicious orc unconscious. Use him to disguise yourself as orc!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L217.1706"] = "[EN] You have no reason to do such an insidious thing.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L232.1707"] = "[EN] You look almost like an orc. It won't fool all orcs, but the stupid guardsman in front of the fortress should fall for it.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L277.1708"] = "[EN] This should be enough distraction for you to sneak into the fortress! Hurry up!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L310.1709"] = "[EN] You poisoned Kraknaknork's soup. This should weaken him immensely. Time to find his room.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L329.1710"] = "[EN] The berserker can't catch you anymore - but only for 20 seconds. You need to lure him away from the teleporter!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L362.1711"] = "[EN] As long as the orc berserker is near that teleporter, you can't enter.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L370.1712"] = "[EN] You're entering Kraknaknork's lair.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L483.1713"] = "[EN] An energy barrier somewhere temporarily disappeared.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L516.1714"] = "[EN] With his last energy, Kraknaknork pushes you out of his throne room. Hurry back and defeat him before he regains his power.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L549.1715"] = "[EN] A player is already inside the boss room.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L564.1716"] = "[EN] You're entering Kraknaknork's throne room. You have 5 minutes to kill him!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L595.1717"] = "[EN] You backed out of the fight. You may try again at any time.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L624.1718"] = "[EN] You may not use this teleporter yet.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L684.1719"] = "[EN] You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L686.1720"] = "[EN] You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L691.1721"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L717.1722"] = "[EN] With Kraknaknork's final source of energy, you escape the fortress. Time to return to Vascalir.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L776.1723"] = "[EN] You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L778.1724"] = "[EN] You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L783.1725"] = "The",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.bursting.at.the.seams.museum.actions.doors.L18.2291"] = "[EN] The door seems to be sealed against unwanted intruders.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.actions.telescope.L6.2318"] = "[EN] The telescope provides a perfect view over the endless ocean - no land in sight",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L13.2312"] = "[EN] You see the scattered parts of a wrecked ship. Miraculously the ship telescope survived the wreckm it seems still to be intact.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L16.2313"] = "[EN] There are still some loose planks and hawsers. You can't use the raft like this, it will sink for sure.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L21.2314"] = "[EN] You use the hawser to lash up the loose planks. The raft should be seaworthy now.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L27.2315"] = "[EN] You see the scattered parts of a wrecked ship. Miraculously the ship telescope survived the wreck it seems still to be intact.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L30.2316"] = "[EN] Witout any points of orientation you will never find your way back. Try to find a way to improve your navigation.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.stepIn.L91.2317"] = "[EN] You must wait. Someone is challenging",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.library.area.movements.mazzinor.L13.2290"] = "[EN] The remains deporalize you temporaly.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.bonefiddle.L16.2302"] = "[EN] You tack the hair to the ebony fingerboard. The strands should be adquate to serve as strings.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.bonefiddle.L27.2303"] = "[EN] *There was once a maiden fair, with dark eyes and silken hair. Far away from home she died. No grave, no wake, no mourning.*",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.bonefiddle.L31.2304"] = "[EN] You are playing the Peacock Ballad and the portal opens.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.bonefiddle.L37.2305"] = "[EN] You are playing the bone fiddle.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.bonefiddle.L9.2301"] = "[EN] You attach the ebony wood to the skull. This should meet the requirements of a fingerboard.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.doors.L16.2310"] = "[EN] You do not have enough level.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.doors.L19.2311"] = "[EN] The door seems to be sealed against unwanted intruders.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.fragrance.L4.2306"] = "[EN] Hmmmm, what an infatuating fragrance!",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.movements.elemental.portals.L111.2308"] = "[EN] You can not use this portal yet.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.movements.elemental.portals.L142.2309"] = "[EN] You have discovered an old writing desk that contains an ancient map.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.movements.elemental.portals.L92.2307"] = "[EN] You took too long, the battle has ended.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.order.of.the.falcon.actions.doors.L47.2299"] = "[EN] The door seems to be sealed against unwanted intruders.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.order.of.the.falcon.actions.doors.L65.2300"] = "[EN] You can not use this boat yet.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.order.of.the.falcon.actions.entrance.L17.2297"] = "[EN] Once more you mix the chalk with a drop of your blood and a bit of water and renew the symbol on the floor...",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.order.of.the.falcon.actions.entrance.L21.2298"] = "[EN] You can only use this entrance during the night.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.parth.of.defiances.desert.actions.chests.L20.2293"] = "[EN] You have found a",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.parth.of.defiances.desert.actions.chests.L22.2294"] = "[EN] It is empty.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.parth.of.defiances.desert.actions.doors.L22.2296"] = "[EN] The door seems to be sealed against unwanted intruders.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.parth.of.defiances.desert.movements.sacrifice.foods.L224.2295"] = "[EN] You have completed the food offering ritual!",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.parth.of.defiances.desert.movements.teleportTo.L127.2292"] = "[EN] You must wait. Someone is challenging Furious Scorpion now.",
